import re
URL = "https://www.oregonlegislature.gov/bills_laws/ors/ors%s.html"
LETTER = re.compile(r"\b(\d{1,3}[A-Z])\.\d{3}")
PARA = re.compile(r'<p class=MsoNormal[^>]*>(.*?)</p>', re.S)
BOLD = re.compile(r'\s*(?:<(?!b>)[^>]+>\s*)*<b>(.*?)</b>', re.S)
SID = re.compile(r'(\d+[A-Z]?\.\d+[A-Za-z0-9]*)(?:\s+(.*))?$', re.S)
NOTE = re.compile(r'Note( \d+)?:')
SUB = re.compile(r'\(\d+\)|\([a-zA-Z]{1,5}\) ')

def txt(h):
    return block_text("<div id=x>%s</div>" % " ".join(h.split()), id="x")

def is_heading(t):
    if t == t.upper() and re.search("[A-Z]{3}", t):
        return True
    return t.startswith("(") and t.endswith(")") and t.count("(") == 1 and not SUB.match(t)

def sections():
    # The chapter list is a SharePoint library that is not public; numeric chapters 1-838 are walked, and lettered
    # chapters (79A, 475C ...) are found from the code's own cross-references and renumbering notes.
    queue, done_ch = ["%03d" % n for n in range(1, 839)], set()
    while queue:
        n = queue.pop(0)
        if n in done_ch:
            continue
        done_ch.add(n)
        url = URL % n
        try:
            _, page = fetch(url)
        except Exception as e:
            if "404" not in str(e):
                log("chapter %s failed %r" % (n, e))
            continue
        for ch in sorted(set(LETTER.findall(page))):
            key = "%03d%s" % (int(ch[:-1]), ch[-1])
            if key not in done_ch and key not in queue:
                queue.append(key)
        cur, seen, count, dups = None, set(), 0, 0
        def done(c):
            return {"id": c[0], "heading": c[1], "text": "\n".join(c[2]), "url": url}
        for m in PARA.finditer(page):
            inner = m.group(1)
            t = txt(inner)
            if not t:
                continue
            b = BOLD.match(inner)
            s = SID.match(txt(b.group(1))) if b else None
            if s:
                if cur and cur[2]:
                    count += 1
                    yield done(cur)
                cur = None
                sid, head = s.group(1), " ".join((s.group(2) or "").split())
                rest = txt(inner[b.end():])
                if not head or head.startswith("[") or sid in seen:
                    dups += sid in seen
                    continue
                seen.add(sid)
                cur = (sid, head.rstrip(".").strip(), [rest] if rest else [])
            elif NOTE.match(t) or is_heading(t):
                if cur and cur[2]:
                    count += 1
                    yield done(cur)
                cur = None
            elif cur:
                cur[2].append(t)
        if cur and cur[2]:
            count += 1
            yield done(cur)
        log("chapter %s sections=%d%s" % (n, count, " (later versions skipped: %d)" % dups if dups else ""))
